use vstd::prelude::*;

verus! {

fn putmask(a: Vec<f32>, mask: Vec<bool>, values: Vec<f32>) -> (result: Vec<f32>)
    requires
        a.len() == mask.len(),
        values.len() > 0,
    ensures
        result.len() == a.len(),
        forall |i: usize| i < a.len() ==>
            if mask[i] {
                // at masked positions we pick the replacement at i mod values.len()
                result[i] == values[i % values.len()]
            } else {
                // at unmasked positions we keep the original
                result[i] == a[i]
            }
{
    let len = a.len();
    let vlen = values.len();
    let mut res: Vec<f32> = Vec::new();
    let mut i: usize = 0;

    // We build res element‐by‐element up to index i
    while i < len
        invariant
            // we have filled res[0..i)
            res.len() == i,
            i <= len,
            values.len() > 0,
            forall |j: usize| j < i ==>
                if mask[j] {
                    res[j] == values[j % vlen]
                } else {
                    res[j] == a[j]
                }
        decreases len - i,
    {
        if mask[i] {
            // pick from values at circular index
            let pick: f32 = values[i % vlen];
            res.push(pick);
        } else {
            // keep from original array
            res.push(a[i]);
        }
        i = i + 1;
    }

    res
}

} // verus! block

